const express = require('express');
const helmet = require('helmet');

const app = express();

// Security configuration from environment variables with sane defaults
const SECURITY_CONFIG = {
  // Body parsing limits
  JSON_LIMIT: process.env.JSON_LIMIT || '10mb',
  URL_ENCODED_LIMIT: process.env.URL_ENCODED_LIMIT || '10mb',

  // Content Security Policy
  CSP_DEFAULT_SRC: process.env.CSP_DEFAULT_SRC ? process.env.CSP_DEFAULT_SRC.split(',') : ["'self'"]
};

// Security middleware - should be used early in the middleware stack
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: SECURITY_CONFIG.CSP_DEFAULT_SRC
    }
  },
  hidePoweredBy: true,
}));

// Set the port from environment variable or default to 3000
const PORT = process.env.PORT || 3000;

// Parse JSON bodies with configurable limit
app.use(express.json({ limit: SECURITY_CONFIG.JSON_LIMIT }));

// Parse URL-encoded bodies with configurable limit
app.use(express.urlencoded({ 
  extended: true, 
  limit: SECURITY_CONFIG.URL_ENCODED_LIMIT 
}));

// Error messages from environment variables with defaults
const ERROR_MESSAGES = {
  NOT_FOUND: process.env.ERROR_MESSAGE_NOT_FOUND || 'Route not found',
  SERVER_ERROR: process.env.ERROR_MESSAGE_SERVER_ERROR || 'Something went wrong!'
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString()
  });
});

// Users endpoint
app.get('/users', (req, res) => {
  // In a real application, this data would come from a database
  // with proper authentication and authorization
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: ERROR_MESSAGES.NOT_FOUND 
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: ERROR_MESSAGES.SERVER_ERROR
  });
});

// Server host configuration (use 0.0.0.0 for external access, localhost for local)
const HOST = process.env.HOST || '0.0.0.0';

// Start server
app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log('Security middleware enabled');
  console.log('Application started successfully');
});

module.exports = app;

