const request = require('supertest');
const app = require('../app.js');

describe('App Security Tests', () => {
  // Test that no sensitive environment variables are exposed
  test('GET /backdoor should not exist in production', async () => {
    const response = await request(app).get('/backdoor');
    expect(response.status).toBe(404);
  });

  test('GET /health should not expose environment variables', async () => {
    const response = await request(app).get('/health');
    expect(response.body).not.toHaveProperty('environment');
    expect(response.body).not.toHaveProperty('env');
    expect(response.body).toHaveProperty('status');
